import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import '../../scripts/pubspec_lock_sbom.dart';
import '../../scripts/simple_yaml.dart';

const _lock = '''
# Generated by pub
# See https://dart.dev/tools/pub/glossary#lockfile
packages:
  crypto:
    dependency: "direct main"
    description:
      name: crypto
      sha256: c8ea0233063ba03258fbcf2ca4d6dadfefe14f02fab57702265467a19f27fadf
      url: "https://pub.dev"
    source: hosted
    version: "3.0.7"
  flutter:
    dependency: "direct main"
    description: flutter
    source: sdk
    version: "0.0.0"
  flutter_lints:
    dependency: "direct dev"
    description:
      name: flutter_lints
      sha256: "3105dc8492f6183fb076ccf1f351ac3d60564bff92e20bfc4af9cc1651f4e7e1"
      url: "https://pub.dev"
    source: hosted
    version: "6.0.0"
  some_git_pkg:
    dependency: transitive
    description:
      path: "."
      ref: main
      resolved-ref: "0123456789abcdef0123456789abcdef01234567"
      url: "https://github.com/example/some_git_pkg.git"
    source: git
    version: "1.2.3"
sdks:
  dart: ">=3.11.0 <4.0.0"
  flutter: ">=3.44.0"
''';

const _pubspec = '''
name: wellapath_mobile
description: "test"
version: 0.3.0+217
''';

Map<String, Object?> _build([String lock = _lock]) =>
    buildCycloneDxFromPubspecLock(
      pubspecLock: lock,
      pubspecYaml: _pubspec,
      timestamp: DateTime.utc(2026, 11, 7, 12),
      gitCommit: 'abc123',
    );

Map<String, Object?> _component(Map<String, Object?> bom, String name) =>
    (bom['components'] as List).cast<Map<String, Object?>>().singleWhere(
      (c) => c['name'] == name,
    );

void main() {
  group('CycloneDX from pubspec.lock', () {
    test('emits a CycloneDX 1.6 document for the app', () {
      final bom = _build();
      expect(bom['bomFormat'], 'CycloneDX');
      expect(bom['specVersion'], '1.6');
      expect(
        bom['serialNumber'],
        matches(
          RegExp(
            r'^urn:uuid:[0-9a-f]{8}-[0-9a-f]{4}-5[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
          ),
        ),
      );
      final metadata = bom['metadata'] as Map;
      expect(metadata['timestamp'], '2026-11-07T12:00:00.000Z');
      expect((metadata['component'] as Map)['name'], 'wellapath_mobile');
      expect(
        (metadata['component'] as Map)['purl'],
        'pkg:pub/wellapath_mobile@0.3.0%2B217',
      );
    });

    test('lists every package once, sorted, with its pub dependency kind', () {
      final bom = _build();
      final names = (bom['components'] as List)
          .map((c) => (c as Map)['name'])
          .toList();
      expect(names, ['crypto', 'flutter', 'flutter_lints', 'some_git_pkg']);
    });

    test('hosted packages carry purl, sha256 and a distribution link', () {
      final crypto = _component(_build(), 'crypto');
      expect(crypto['purl'], 'pkg:pub/crypto@3.0.7');
      expect(crypto['scope'], 'required');
      expect(crypto['hashes'], [
        {
          'alg': 'SHA-256',
          'content':
              'c8ea0233063ba03258fbcf2ca4d6dadfefe14f02fab57702265467a19f27fadf',
        },
      ]);
      expect(
        (crypto['externalReferences'] as List).single,
        containsPair('url', 'https://pub.dev/packages/crypto/versions/3.0.7'),
      );
    });

    test('direct dev dependencies are optional; sdk and git are recorded', () {
      final bom = _build();
      expect(_component(bom, 'flutter_lints')['scope'], 'optional');
      final flutter = _component(bom, 'flutter');
      expect(flutter['hashes'], isNull);
      expect(
        flutter['properties'],
        contains(equals({'name': 'pub:source', 'value': 'sdk'})),
      );
      final git = _component(bom, 'some_git_pkg');
      expect(
        git['properties'],
        contains(
          equals({
            'name': 'pub:git_resolved_ref',
            'value': '0123456789abcdef0123456789abcdef01234567',
          }),
        ),
      );
    });

    test('output is deterministic for the same lockfile and timestamp', () {
      expect(jsonEncode(_build()), jsonEncode(_build()));
    });

    test('states its limitation and that it is not a certification', () {
      final props = ((_build()['metadata'] as Map)['properties'] as List)
          .map((p) => (p as Map)['name'])
          .toList();
      expect(props, contains('wellapath:limitation'));
      expect(props, contains('wellapath:not_a_certification'));
      expect(props, contains('wellapath:git_commit'));
    });

    test('fails closed on a hosted package without a valid sha256', () {
      final broken = _lock.replaceFirst(
        'c8ea0233063ba03258fbcf2ca4d6dadfefe14f02fab57702265467a19f27fadf',
        'not-a-hash',
      );
      expect(() => _build(broken), throwsA(isA<SbomException>()));
    });

    test('fails closed on a lockfile without packages', () {
      expect(
        () => _build('sdks:\n  dart: ">=3.0.0"\n'),
        throwsA(isA<SbomException>()),
      );
      expect(
        () => _build('packages: [1]'),
        throwsA(isA<YamlSubsetException>()),
      );
    });

    test('covers every package in the real pubspec.lock', () {
      final lock = File('pubspec.lock').readAsStringSync();
      final bom = buildCycloneDxFromPubspecLock(
        pubspecLock: lock,
        pubspecYaml: File('pubspec.yaml').readAsStringSync(),
        timestamp: DateTime.utc(2026),
      );
      final expected = RegExp(
        r'^    dependency:',
        multiLine: true,
      ).allMatches(lock).length;
      expect((bom['components'] as List).length, expected);
      expect(expected, greaterThan(50));
    });
  });
}
